        try:
            der_sig = raw_to_der_signature(sig, key.curve)
        except ValueError:
            return False

        try:
            public_key = (
                key.public_key()
                if isinstance(key, EllipticCurvePrivateKey)
                else key
            )
            public_key.verify(der_sig, msg, ECDSA(self.hash_alg()))
