        elif curve == "P-384":
            if len(x) == len(y) == 48:
                curve_obj = SECP384R1()
            else:
                raise InvalidKeyError(
                    "Coords should be 48 bytes for curve P-384"
                ) from None
        elif curve == "P-521":
            if len(x) == len(y) == 66:
