def _validate_required_claims(
    self,
    payload: dict[str, Any],
    claims: Iterable[str],
) -> None:
    for claim in claims:
        if payload.get(claim) is None:
            raise MissingRequiredClaimError(claim)

method:jwt/api_jwt.py::PyJWT._validate_s.code:
def _validate_sub(
    self, payload: dict[str, Any], subject: str | None = None
) -> None:
    """
    Checks whether "sub" if in the payload is valid or not.
    This is an Optional claim

    :param payload(dict): The payload which needs to be validated
    :param subject(str): The subject of the token
    """

    if "sub" not in payload:
        return

    if not isinstance(payload["sub"], str):
        raise InvalidSubjectError("Subject must be a string")

    if subject is not None:
        if payload.get("sub") != subject:
            raise InvalidSubjectError("Invalid subject")

method:jwt/api_jwt.py::PyJWT._validate_j.code:
def _validate_jti(self, payload: dict[str, Any]) -> None:
    """
    Checks whether "jti" in the payload is valid or not
    This is an Optional claim

    :param payload(dict): The payload which needs to be validated
    """

    if "jti" not in payload:
        return

    if not isinstance(payload.get("jti"), str):
        raise InvalidJTIError("JWT ID must be a string")

method:jwt/api_jwt.py::PyJWT._validate_i.code:
def _validate_iat(
    self,
    payload: dict[str, Any],
    now: float,
    leeway: float,
) -> None:
    try:
        iat = int(payload["iat"])
    except (ValueError, TypeError, OverflowError):
        raise InvalidIssuedAtError(
            "Issued At claim (iat) must be an integer."
        ) from None
    if iat > (now + leeway):
        raise ImmatureSignatureError("The token is not yet valid (iat)")

method:jwt/api_jwt.py::PyJWT._validate_n.code:
def _validate_nbf(
    self,
    payload: dict[str, Any],
    now: float,
    leeway: float,
) -> None:
    try:
        nbf = int(payload["nbf"])
    except (ValueError, TypeError, OverflowError):
        raise DecodeError("Not Before claim (nbf) must be an integer.") from None

    if nbf > (now + leeway):
        raise ImmatureSignatureError("The token is not yet valid (nbf)")

method:jwt/api_jwt.py::PyJWT._validate_e.code:
def _validate_exp(
    self,
    payload: dict[str, Any],
    now: float,
    leeway: float,
) -> None:
    try:
        exp = int(payload["exp"])
    except (ValueError, TypeError, OverflowError):
        raise DecodeError(
            "Expiration Time claim (exp) must be an integer."
        ) from None

    if exp <= (now - leeway):
        raise ExpiredSignatureError("Signature has expired")

method:jwt/api_jwt.py::PyJWT._validate_a.code:
def _validate_aud(
    self,
    payload: dict[str, Any],
    audience: str | Iterable[str] | None,
    *,
    strict: bool = False,
) -> None:
    if audience is None:
        if "aud" not in payload or not payload["aud"]:
            return
        # Application did not specify an audience, but
        # the token has the 'aud' claim
        raise InvalidAudienceError("Invalid audience")

    if "aud" not in payload or not payload["aud"]:
        # Application specified an audience, but it could not be
        # verified since the token does not contain a claim.
        raise MissingRequiredClaimError("aud")

    audience_claims = payload["aud"]

    # In strict mode, we forbid list matching: the supplied audience
    # must be a string, and it must exactly match the audience claim.
    if strict:
        # Only a single audience is allowed in strict mode.
        if not isinstance(audience, str):
            raise InvalidAudienceError("Invalid audience (strict)")

        # Only a single audience claim is allowed in strict mode.
        if not isinstance(audience_claims, str):
            raise InvalidAudienceError("Invalid claim format in token (strict)")

        if audience != audience_claims:
            raise InvalidAudienceError("Audience doesn't match (strict)")

        return

    if isinstance(audience_claims, str):
        audience_claims = [audience_claims]
    if not isinstance(audience_claims, list):
        raise InvalidAudienceError("Invalid claim format in token")
    if any(not isinstance(c, str) for c in audience_claims):
        raise InvalidAudienceError("Invalid claim format in token")

    if isinstance(audience, str):
        audience = [audience]

    if all(aud not in audience_claims for aud in audience):
        raise InvalidAudienceError("Audience doesn't match")

method:jwt/api_jwt.py::PyJWT._validate_i.code:
def _validate_iss(
    self, payload: dict[str, Any], issuer: Container[str] | str | None
) -> None:
    if issuer is None:
        return

    if "iss" not in payload:
        raise MissingRequiredClaimError("iss")

    iss = payload["iss"]
    if not isinstance(iss, str):
        raise InvalidIssuerError("Payload Issuer (iss) must be a string")

    if isinstance(issuer, str):
        if iss != issuer:
            raise InvalidIssuerError("Invalid issuer")
    else:
        try:
            if iss not in issuer:
                raise InvalidIssuerError("Invalid issuer")
        except TypeError:
            raise InvalidIssuerError(
                'Issuer param must be "str" or "Container[str]"'
            ) from None

class:jwt/exceptions.py::InvalidTokenErr.code:
class InvalidTokenError(PyJWTError):
    """Base exception when ``decode()`` fails on a token"""

    pass

class:jwt/exceptions.py::DecodeError.code:
class DecodeError(InvalidTokenError):
    """Raised when a token cannot be decoded because it failed validation"""

    pass

class:jwt/exceptions.py::ExpiredSignatur.code:
class ExpiredSignatureError(InvalidTokenError):
    """Raised when a token's ``exp`` claim indicates that it has expired"""

    pass

class:jwt/exceptions.py::InvalidIssuerEr.code:
class InvalidIssuerError(InvalidTokenError):
    """Raised when a token's ``iss`` claim does not match the expected issuer"""

    pass

class:jwt/exceptions.py::InvalidIssuedAt.code:
class InvalidIssuedAtError(InvalidTokenError):
    """Raised when a token's ``iat`` claim is non-numeric"""

    pass

class:jwt/exceptions.py::ImmatureSignatu.code:
class ImmatureSignatureError(InvalidTokenError):
    """Raised when a token's ``nbf`` or ``iat`` claims represent a time in the future"""

    pass

class:jwt/exceptions.py::InvalidKeyError.code:
class InvalidKeyError(PyJWTError):
    """Raised when the specified key is not in the proper format"""

    pass

class:jwt/exceptions.py::InvalidAlgorith.code:
class InvalidAlgorithmError(InvalidTokenError):
    """Raised when the specified algorithm is not recognized by PyJWT"""

    pass

class:jwt/exceptions.py::MissingRequired.code:
class MissingRequiredClaimError(InvalidTokenError):
    """Raised when a claim that is required to be present is not contained
    in the claimset"""

    def __init__(self, claim: str) -> None:
        self.claim = claim

    def __str__(self) -> str:
        return f'Token is missing the "{self.claim}" claim'

class:jwt/exceptions.py::MissingCryptogr.code:
class MissingCryptographyError(PyJWKError):
