method:jwt/jwks_client.py::PyJWKClient._.code:
def _as_jwk_set_payload(data: Any) -> dict[str, Any]:
    if not isinstance(data, dict):
        raise PyJWKClientError("The JWKS endpoint did not return a JSON object")

    return data

def _get_signing_keys_from_jwk_set(jwk_set: PyJWKSet) -> list[PyJWK]:
    signing_keys = [
        jwk_set_key
        for jwk_set_key in jwk_set.keys
        if jwk_set_key.public_key_use in ["sig", None] and jwk_set_key.key_id
    ]

    if not signing_keys:
        raise PyJWKClientError("The JWKS endpoint did not contain any signing keys")

    return signing_keys

function:jwt/utils.py::force_bytes.code:
def force_bytes(value: Union[bytes, str]) -> bytes:
    if isinstance(value, str):
        return value.encode("utf-8")
    elif isinstance(value, bytes):
        return value
    else:
        raise TypeError("Expected a string or bytes value")

function:jwt/utils.py::base64url_decode.code:
def base64url_decode(input: Union[bytes, str]) -> bytes:
    input_bytes = force_bytes(input)

    rem = len(input_bytes) % 4

    if rem > 0:
        input_bytes += b"=" * (4 - rem)

    return base64.urlsafe_b64decode(input_bytes)

